statement:
Each row of `restaurants` describes one place as `[id, rating, veganFriendly, price, distance]`, where the vegan flag is `1` for vegan-friendly and `0` otherwise. A restaurant survives the filters when all of these hold:

- if the argument `veganFriendly` is `1`, the restaurant's own vegan flag is `1` (when the argument is `0`, the flag does not matter);
- its price is at most `maxPrice`;
- its distance is at most `maxDistance`.

Return the ids of the surviving restaurants, best rating first; when two of them share a rating, the larger id comes first. If none survive, return an empty list.

validator:
function validate([restaurants, veganFriendly, maxPrice, maxDistance]) {
  if (restaurants.length < 1 || restaurants.length > 10000) return 'restaurants needs 1 to 10000 rows.';
  const ids = new Set();
  for (const row of restaurants) {
    if (!Array.isArray(row) || row.length !== 5) return 'Each restaurant is [id, rating, veganFriendly, price, distance].';
    const [id, rating, vegan, price, distance] = row;
    if ([id, rating, price, distance].some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'id, rating, price and distance are whole numbers from 1 to 100000.';
    if (vegan !== 0 && vegan !== 1) return "A restaurant's vegan flag is 0 or 1.";
    if (ids.has(id)) return 'Restaurant ids must be distinct.';
    ids.add(id);
  }
  if (veganFriendly !== 0 && veganFriendly !== 1) return 'veganFriendly is 0 or 1.';
  if (!Number.isInteger(maxPrice) || maxPrice < 1 || maxPrice > 100000) return 'maxPrice is a whole number from 1 to 100000.';
  if (!Number.isInteger(maxDistance) || maxDistance < 1 || maxDistance > 100000) return 'maxDistance is a whole number from 1 to 100000.';
  return null;
}

