function filterRestaurants(restaurants, veganFriendly, maxPrice, maxDistance) {
  const kept = restaurants.filter(([id, rating, vegan, price, distance]) =>
    (veganFriendly === 0 || vegan === 1) &&
    price <= maxPrice &&
    distance <= maxDistance
  );

  kept.sort((a, b) => {
    if (a[1] !== b[1]) {
      return b[1] - a[1];
    }
    return b[0] - a[0];
  });

  return kept.map(([id]) => id);
}

