function filterRestaurants(restaurants, veganFriendly, maxPrice, maxDistance) {
  const pool = [];
  for (const r of restaurants) {
    if (veganFriendly === 1 && r[2] !== 1) continue;
    if (r[3] > maxPrice || r[4] > maxDistance) continue;
    pool.push(r);
  }
  // Selection: repeatedly take the remaining restaurant that should come first.
  const out = [];
  while (pool.length) {
    let pick = 0;
    for (let j = 1; j < pool.length; j++) {
      const better = pool[j][1] > pool[pick][1] || (pool[j][1] === pool[pick][1] && pool[j][0] > pool[pick][0]);
      if (better) pick = j;
    }
    out.push(pool[pick][0]);
    pool.splice(pick, 1);
  }
  return out;
}

