function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  const top = size === 'large' ? 100000 : 30;
  // Small inputs use a narrow rating range so that ties (broken by id) are common.
  const ratingTop = size === 'large' ? 1 + Math.floor(rand() * 100000) : 1 + Math.floor(rand() * 5);
  const pick = (hi) => 1 + Math.floor(rand() * hi);
  const ids = new Set();
  while (ids.size < n) ids.add(pick(top));
  // Ids come out of the set in random order, so they rarely match positions.
  const restaurants = [...ids].map(id => [id, pick(ratingTop), rand() < 0.5 ? 1 : 0, pick(top), pick(top)]);
  return [restaurants, rand() < 0.5 ? 1 : 0, pick(top), pick(top)];
}
